#!/usr/bin/env node
/** Regenerates src/diagnostics/roslyn-codes.js from the pinned Roslyn resource dump.
 * The generated table keeps every code it already lists, adds each CSxxxx literal found under
 * packages/compiler/src, and adds any codes passed on the command line (`node generate-diagnostic-codes.js CS0104 CS0234`).
 * `--check` exits non-zero when the generated file is stale instead of writing it.
 */
import {readFileSync,writeFileSync,readdirSync,existsSync} from 'node:fs';
import {dirname,resolve,join} from 'node:path';
import {fileURLToPath} from 'node:url';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'..'),target=join(root,'src/diagnostics/roslyn-codes.js');
const dump=JSON.parse(readFileSync(join(root,'test/roslyn/diagnostic-messages.json'),'utf8'));
const wanted=new Set(process.argv.slice(2).filter(a=>/^CS\d{4}$/.test(a)));
if(existsSync(target))for(const m of readFileSync(target,'utf8').matchAll(/^ (CS\d{4}):/gm))wanted.add(m[1]);
const visit=dir=>{for(const e of readdirSync(dir,{withFileTypes:true})){const p=join(dir,e.name);if(e.isDirectory())visit(p);else if(e.name.endsWith('.js')&&p!==target)for(const m of readFileSync(p,'utf8').matchAll(/\bCS\d{4}\b/g))wanted.add(m[0]);}};
visit(join(root,'src'));
const missing=[...wanted].filter(c=>!dump.codes[c]).sort();
if(missing.length)console.error('Not in the pinned Roslyn dump (kept out of the table): '+missing.join(' '));
const codes=[...wanted].filter(c=>dump.codes[c]).sort();
const unsafeCode=code=>/Varargs|VarArgs|Arglist|RefAny|Ptr|Pointer|Fixed|Unsafe/.test(dump.codes[code][0])
  || /__arglist|variable arguments/.test(dump.codes[code][3]);
const row=code=>{
  const [name,severity,level,format]=dump.codes[code];
  return ` ${code}:[${JSON.stringify(name)},${JSON.stringify(severity)},${level},${JSON.stringify(format)}]`;
};
const quoteMessage=format=>{
  const parts=[];let part='';
  for(const character of format){
    if(JSON.stringify(part+character).length>112){parts.push(JSON.stringify(part));part='';}
    part+=character;
  }
  parts.push(JSON.stringify(part));return parts.join('+\n  ');
};
const unsafeRow=code=>{
  const [name,severity,level,format]=dump.codes[code];
  return ` ${code}:[${JSON.stringify(name)},${JSON.stringify(severity)},${level},\n  ${quoteMessage(format)}]`;
};
const banner=`/** GENERATED by packages/compiler/scripts/generate-diagnostic-codes.js from the pinned Roslyn ${dump.roslyn} resource dump. Do not edit.\n`+
  ' * Row shape: code:[Roslyn ErrorCode name, default severity, warning level, message format]. */\n';
const text=banner+`import {unsafeRoslynCodes} from './roslyn-unsafe-codes.js';
export const ROSLYN_VERSION=${JSON.stringify(dump.roslyn)};
const descriptors={
${codes.filter(c=>!unsafeCode(c)).map(row).join(',\n')},
 ...unsafeRoslynCodes
};
export const roslynCodes=Object.freeze(Object.fromEntries(Object.entries(descriptors).sort(([a],[b])=>a.localeCompare(b))));
`;
const unsafeText=banner+`/** Pointer, fixed storage and variable argument diagnostics. */
export const unsafeRoslynCodes=Object.freeze({
${codes.filter(unsafeCode).map(unsafeRow).join(',\n')}
});
`;
let stale=false;
for(const [path,content] of [[target,text],[join(root,'src/diagnostics/roslyn-unsafe-codes.js'),unsafeText]]){
  if(process.argv.includes('--check')){
    if(!existsSync(path)||readFileSync(path,'utf8')!==content){console.error(path+' is stale; run generate-diagnostic-codes.js');stale=true;}
  }else writeFileSync(path,content);
}
if(stale)process.exit(1);
if(!process.argv.includes('--check'))console.log(`Wrote ${codes.length} Roslyn diagnostic descriptors.`);
